B.O_=new A.ae("1. Veri Haz\u0131rlama ve Temizleme",null,B.aB,null,null)
B.az=new A.eB(null,8,null,null)
B.OD=new A.ae("Veri setleri birle\u015ftirildi, eksik veriler dolduruldu ve gereksiz s\xfctunlar temizlendi. Tarih ve say\u0131sal alanlar uygun formatlara d\xf6n\xfc\u015ft\xfcr\xfclerek analiz i\xe7in haz\u0131r h\xe2le getirildi.",null,B.ad,null,null)
B.b1=new A.eB(null,30,null,null)
B.O7=new A.ae("2. Sat\u0131\u015f Performans\u0131 Analizi",null,B.aB,null,null)
B.Ok=new A.ae("2019 ve 2020 y\u0131llar\u0131 ola\u011fan\xfcst\xfc y\xfcksek sat\u0131\u015f hacmi (~850M USD) ile \xf6ne \xe7\u0131km\u0131\u015ft\u0131r. Di\u011fer y\u0131llarda sat\u0131\u015flar ortalama 5\u201310M USD band\u0131nda seyretmi\u015ftir. Sat\u0131\u015flar\u0131n b\xfcy\xfck b\xf6l\xfcm\xfc az say\u0131da m\xfc\u015fteriden gelmektedir (Pareto ilkesi).",null,B.ad,null,null)
B.ND=new A.ae("3. M\xfc\u015fteri Analizi ve Segmentasyonu",null,B.aB,null,null)
B.Oh=new A.ae("Ortalama sipari\u015f b\xfcy\xfckl\xfc\u011f\xfcne g\xf6re m\xfc\u015fteriler:\n\u2022 B\xfcy\xfck Al\u0131c\u0131lar: %50\u2019ye yak\u0131n katk\u0131 sa\u011flar.\n\u2022 Orta Seviye Al\u0131c\u0131lar: %4 oran\u0131ndad\u0131r.\n\u2022 K\xfc\xe7\xfck Al\u0131c\u0131lar: \xc7ok sipari\u015f verir ama katk\u0131s\u0131 d\xfc\u015f\xfckt\xfcr.\n\nSegmentlere g\xf6re farkl\u0131 sat\u0131\u015f stratejileri geli\u015ftirilebilir.",null,B.ad,null,null)
B.Oy=new A.ae("4. Zaman Bazl\u0131 Analiz",null,B.aB,null,null)
B.NT=new A.ae("2019\u20132020 d\xf6neminde sat\u0131\u015f art\u0131\u015f\u0131 belirli m\xfc\u015fterilerden kaynaklanm\u0131\u015ft\u0131r. 2021 sonras\u0131 baz\u0131 b\xfcy\xfck m\xfc\u015fterilerde ciddi d\xfc\u015f\xfc\u015f g\xf6zlemlenmi\u015ftir. Sad\u0131k m\xfc\u015fterilerin oran\u0131 %96,7 ile y\xfcksek olsa da yeni m\xfc\u015fteri kazan\u0131m\u0131 zay\u0131ft\u0131r.",null,B.ad,null,null)
B.Ot=new A.ae("5. RFM Analizi ve M\xfc\u015fteri Segmentleri",null,B.aB,null,null)
B.OA=new A.ae("RFM sonu\xe7lar\u0131na g\xf6re m\xfc\u015fteri da\u011f\u0131l\u0131m\u0131:\n- Champions: %20.4\n- Loyal: %6.1\n- At Risk: %16.3\n- Hibernating: %24.5\n- Need Attention: %32.6",null,B.ad,null,null)
B.NP=new A.ae("6. M\xfc\u015fteri Kay\u0131p (Churn) Analizi",null,B.aB,null,null)
B.NI=new A.ae("2019\u2019da churn oran\u0131 %2.8 iken 2023\u2019te %7\u2019ye y\xfckselmi\u015ftir. S\u0131k sipari\u015f verenlerin churn olas\u0131l\u0131\u011f\u0131 d\xfc\u015f\xfckt\xfcr. Hibernating segmentinde churn oran\u0131 %67 seviyesindedir.",null,B.ad,null,null)
B.OC=new A.ae("7. B\xf6lgesel Sat\u0131\u015f Da\u011f\u0131l\u0131m\u0131",null,B.aB,null,null)
B.Oa=new A.ae("ABD en b\xfcy\xfck pazar (~46 m\xfc\u015fteri), Kanada ve Almanya\u2019da b\xfcy\xfcme potansiyeli vard\u0131r. Eyalet baz\u0131nda Georgia ve California \xf6ne \xe7\u0131kmaktad\u0131r. D\xfc\u015f\xfck yo\u011funluklu eyaletlerde yeni m\xfc\u015fteri f\u0131rsatlar\u0131 vard\u0131r.",null,B.ad,null,null)
B.OB=new A.ae("8. Stratejik \xd6neriler",null,B.aB,null,null)
B.NK=new A.ae("\u2022 Champions & Loyal: Sadakat programlar\u0131 ve ki\u015fisel teklifler.\n\u2022 At Risk & Hibernating: Yeniden kazanma kampanyalar\u0131.\n\u2022 Need Attention: Promosyonlarla etkile\u015fimi art\u0131r.",null,B.ad,null,null)
